pub const PLANET_TEXTURES: &[&[&[(f32, f32)]]] = &[
    TEXTURE_GRADIENT1,
    TEXTURE_CONTOUR1,
    TEXTURE_CONTOUR2,
    TEXTURE_CONTOUR3,
    TEXTURE_PLANET17,
    TEXTURE_PLANET17_NOSTORM,
    TEXTURE_BIGRADIENT,
    TEXTURE_BANDS1,
    TEXTURE_BANDS2,
    TEXTURE_OFFSET_CIRCLES,
];

/// Planet textures are specified in the coordinate system 0..PLANET_TEXTURE_SIZE.
pub const PLANET_TEXTURE_SIZE: f32 = 128.0;

/// Color in sRGB, components 0..1. Conversion to linear space is done by the renderer.
pub struct LinearColor(pub f32, pub f32, pub f32, pub f32);

pub const EIGENGRAU: LinearColor = LinearColor(0.086, 0.086, 0.114, 1.0); // 0xFF16161D
